-- 1. Enable extension
CREATE EXTENSION IF NOT EXISTS vector;

-- 2. Create documents table with 1536-dimensional vector (OpenAI text-embedding-3-small)
CREATE TABLE document_chunks (
    id SERIAL PRIMARY KEY,
    content TEXT NOT NULL,
    embedding vector(1536) NOT NULL
);

-- 3. Create HNSW index using cosine distance
CREATE INDEX idx_chunks_hnsw ON document_chunks 
USING hnsw (embedding vector_cosine_ops);

-- 4. Nearest Neighbor Query (Cosine Distance <=>)
SELECT id, content, 1 - (embedding <=> $query_embedding) AS similarity_score
FROM document_chunks
ORDER BY embedding <=> $query_embedding ASC
LIMIT 5;

CREATE TABLE documents (
    id        bigserial PRIMARY KEY,
    content   text NOT NULL,
    embedding vector(1536) NOT NULL
);

CREATE INDEX idx_documents_embedding
ON documents
USING hnsw (embedding vector_cosine_ops)
WITH (m = 16, ef_construction = 64);

SELECT id, content
FROM documents
ORDER BY embedding <=> '[0.01, 0.02, ...]'::vector
LIMIT 5;
